/**
 * Salida del núcleo (§5.1).
 *
 * Se construye desde `RunState` omitiendo todo lo interno: hechos candidatos
 * sin verificar, nodos completados, reintentos e invocaciones de modelo no
 * salen de la orquestación.
 */
export interface RunResult {
  answer?: Answer;
  available_actions?: AvailableActions;
  catalog_version?: CatalogVersion;
  error?: NormalizedError | null;
  estimate?: Estimate | null;
  fallback?: ChannelFallback | null;
  metrics?: RunMetrics;
  questions?: Questions;
  run_id: RunId;
  skill_id?: SkillId;
  skill_version?: SkillVersion;
  sources?: Sources;
  status: RunStatus;
  surface?: A2UISurface | null;
  trace_id: TraceId;
  verified_facts?: VerifiedFacts | null;
  warnings?: Warnings;
}
/**
 * Acción opaca ligada a un schema, una versión y un run concreto (§5.5).
 */
export interface A2UIAction {
  action_id: ActionId;
  expected_version: ExpectedVersion;
  input_schema_ref: InputSchemaRef;
  label: Label;
  requires_confirmation?: RequiresConfirmation;
  tool_name: ToolName;
}
/**
 * Error normalizado que cruza cualquier frontera de Nexo IA.
 *
 * `outcome` es el campo que impide reintentos peligrosos: un `UNKNOWN`
 * significa que no sabemos si la operación tuvo efecto, y por tanto nunca se
 * reintenta de forma automática (`DIE-F0-035`).
 */
export interface NormalizedError {
  code: ErrorCode;
  details?: Details;
  message: Message;
  outcome?: Outcome;
  retry_after_ms?: RetryAfterMs;
  retryable: Retryable;
}
/**
 * Detalle accionable de un error, sin contenido sensible.
 */
export interface ErrorDetail {
  field?: Field;
  reason: Reason;
}
/**
 * Resultado del estimador: pasos ordenados, costo total y trazabilidad.
 */
export interface Estimate {
  derived_from?: DerivedFrom;
  domain: Domain;
  steps?: Steps;
  total_cost?: Money | null;
}
/**
 * Un trámite dentro de la ruta calculada, con dependencias estables.
 */
export interface EstimateStep {
  cost?: Money | null;
  depends_on?: DependsOn;
  derived_from: DerivedFrom1;
  duration_days?: DurationDays;
  missing_documents?: MissingDocuments;
  step_id: StepId;
  title: Title;
}
/**
 * Monto en unidades menores más moneda (§2.3).
 *
 * Nunca se representa un monto en flotante ni se suma en un prompt: el
 * estimador opera sobre `amount_minor` con código determinista.
 */
export interface Money {
  amount_minor: AmountMinor;
  currency: Currency;
}
/**
 * Representación segura cuando la superficie no puede renderizarse (§5.5).
 *
 * Nunca queda vacío: si A2UI falla, el canal recibe texto plano equivalente en
 * lugar de nada (`DIE-F1-106`).
 */
export interface ChannelFallback {
  action_hint?: ActionHint;
  channel: Channel;
  numbered_items?: NumberedItems;
  reason: Reason1;
  text: Text;
}
/**
 * Métricas obligatorias del run. El gate exige que el 100% las registre.
 */
export interface RunMetrics {
  duration_ms?: DurationMs;
  first_event_ms?: FirstEventMs;
  model_invocation_count?: ModelInvocationCount;
  question_count?: QuestionCount;
  retrieval_count?: RetrievalCount;
  tool_call_count?: ToolCallCount;
  total_cost_usd?: TotalCostUsd;
  total_input_tokens?: TotalInputTokens;
  total_output_tokens?: TotalOutputTokens;
}
/**
 * Referencia puntual a un fragmento de una fuente (§5.2).
 *
 * Es inmutable a propósito: una citación es evidencia, y la evidencia no se
 * edita después de recogerse.
 */
export interface SourceCitation {
  char_end?: CharEnd;
  char_start?: CharStart;
  corpus_version: CorpusVersion;
  fragment_id: FragmentId;
  is_active?: IsActive;
  source_id: SourceId;
  source_version: SourceVersion;
  valid_from: ValidFrom;
  valid_to?: ValidTo;
}
/**
 * Superficie completa: la secuencia ordenada de mensajes más sus acciones.
 */
export interface A2UISurface {
  actions?: Actions;
  catalog_id: CatalogId;
  channel: Channel;
  messages: Messages;
  surface_id: SurfaceId;
}
/**
 * Unidad JSONL del protocolo: exactamente uno de los tres mensajes.
 */
export interface A2UIMessage {
  createSurface?: CreateSurface | null;
  updateComponents?: UpdateComponents | null;
  updateDataModel?: UpdateDataModel | null;
  version?: Version;
}
export interface CreateSurface {
  catalogId: Catalogid;
  sendDataModel?: Senddatamodel;
  surfaceId: Surfaceid;
}
export interface UpdateComponents {
  components: Components;
  surfaceId: Surfaceid1;
}
/**
 * Nodo del árbol de componentes.
 *
 * Los datos viven en el data model y se referencian por binding (`{"path": ...}`);
 * la estructura nunca los incrusta (`DIE-F1-102`).
 *
 * En el protocolo, las propiedades específicas del componente viajan aplanadas
 * junto a `id` y `component`. Aquí se validan agrupadas bajo `properties` para
 * mantener el modelo cerrado, y la (de)serialización hace la conversión: los
 * fixtures que consume el renderer de Cris salen con la forma del protocolo,
 * sin traducción implícita a cargo del consumidor (`DIE-F0-019`).
 */
export interface A2UIComponent {
  actionId?: Actionid;
  children?: Children;
  component: Component;
  id: Id;
  properties?: Properties;
}
export interface Properties {
  [k: string]: JsonValue;
}
export interface UpdateDataModel {
  path: Path;
  surfaceId: Surfaceid2;
  value: JsonValue;
}
/**
 * Snapshot inmutable que reciben estimación final, A2UI y redactor (§5.2).
 *
 * El redactor solo ve esto: no tiene puertos de RAG ni de MCP, así que este
 * snapshot es literalmente el universo de hechos del que puede hablar
 * (`DIE-F1-094`).
 */
export interface VerifiedFacts {
  contradictions?: Contradictions;
  created_at: CreatedAt;
  facts: Facts;
  snapshot_id: SnapshotId;
}
/**
 * Conflicto detectado entre hechos, fuentes o resultados de tools (§5.2).
 */
export interface Contradiction {
  conflicting_sources?: ConflictingSources;
  conflicting_tool_calls?: ConflictingToolCalls;
  contradiction_id: ContradictionId;
  explanation: Explanation;
  fact_ids: FactIds;
  resolved_fact_id?: ResolvedFactId;
  rule: Rule;
  severity: ContradictionSeverity;
  status?: ContradictionStatus;
}
/**
 * Hecho tras pasar por el verificador (§5.2).
 *
 * Invariante central: si es crítico y fue aceptado, tiene al menos una
 * citación activa y es apto para escritura solo si además está aceptado.
 */
export interface VerifiedFact {
  category: FactCategory;
  citations?: Citations;
  claim: Claim;
  confidence: Confidence;
  depends_on?: DependsOn1;
  domain: Domain;
  fact_id: FactId;
  reason: Reason2;
  supporting_tool_call_id?: SupportingToolCallId;
  value: FactValue;
  verification: VerificationStatus;
  write_eligible?: WriteEligible;
}
/**
 * Valor tipado de un hecho.
 *
 * Se modela como una unión explícita en lugar de `Any` para que el estimador
 * nunca tenga que adivinar el tipo antes de sumar o comparar.
 */
export interface FactValue {
  boolean?: Boolean;
  date?: Date;
  items?: Items;
  money?: Money | null;
  number?: Number;
  text?: Text1;
}
